    getUsrGroups: function getUsrGroups(selServTemp) {
      var usrgroups;
      var url = '/api/v3/request_templates/' + selServTemp; // url variable introduced for modifying in MSP/SCP
      if (this.ismsp) {
        url = url + '/account_user_groups'; // NO I18N
        var selAcclistStr = $('#ac_list').val();
        if ($('#allACPopup').is(':checked') || selAcclistStr != '') {
          var input_data = {
            "request_templates": {// NO I18N
            }
          };
          if (selAcclistStr != '') {
            var selAcclist = selAcclistStr.split(',');
            var accList = [];
            for (var i = 0; i < selAcclist.length; i++) {
              var val = selAcclist[i];
              if (val !== '') {
                accList.push({
                  id: val
                });
              }
            }
            if (accList.length > 0) {
              input_data.request_templates.account_ids = accList;
            }
          }
          sdpAjax({
            method: 'POST',
            // No I18N
            url: url,
            // No I18N
            data: sdpAjaxInputData(input_data),
            async: false,
            success: function success(obj) {
              usrgroups = obj.account_user_groups;
            },
            cache: false
          });
        } else {
          usrgroups = [];
        }
      } else {
        sdpAjax({
          method: 'GET',
          // No I18N
          url: url,
          async: false,
          success: function success(resp) {
            usrgroups = resp.request_template.user_groups;
          },
          cache: false
        });
      }
      return usrgroups;
    },
