    // Construct search criteria.
    getsearchCriteria: function getsearchCriteria(options) {
      // Get module.
      var get_module = this.get('module');
      if (get_module == "rcf") {
        var cf_module = 'request';
      } else if (get_module == "ccf") {
        var cf_module = 'change';
      } else if (get_module == "tcf") {
        var cf_module = 'task';
      } else if (get_module == "pcf") {
        var cf_module = 'project';
      } else if (get_module == "pbcf") {
        var cf_module = 'problem';
      } else if (get_module == "zcf") {
        var cf_module = 'zia';
      } else if (get_module == "relcf") {
        var cf_module = 'release';
      } else if (get_module == "ntcf") {
        var cf_module = 'note';
      } else if (get_module == "ncf") {
        var cf_module = 'notification';
      } else if (get_module == "alcf") {
        var cf_module = 'approval_level';
      } else if (get_module == "acf") {
        var cf_module = 'approval';
      } else if (get_module == "cmcf") {
        var cf_module = this.get("cm_filter").name;
      }
      var search_array = [];
      // Get current filter.
      var current_filter = options.popup ? this.get("popup_filter") : this.get("list_filter");
      // Get function type.
      var current_funct_type = "";
      if (this.get("selected_tab") == "custom-actions") {
        current_funct_type = "customaction";
        /** Custom Schedule function **/
        if (get_module == "csf") {
          current_funct_type = "schedule";
        } else if (get_module == "cbf") {
          current_funct_type = "callback";
        } else if (get_module == "zcf") {
          current_funct_type = "ziaaction";
        }
      } else {
        current_funct_type = "global";
      }
      if (options.function_type) {
        if (["rcf", "ntcf", "ncf", "alcf", "acf", "cmcf"].includes(get_module) && ["all_action", "trigger_action", "br_action"].includes(current_filter)) {
          search_array.push({
            "field": "function_type",
            "condition": "in",
            "values": ["conditional", "customaction"],
            "logical_operator": "and"
          });
        } else {
          search_array.push({
            "field": "function_type",
            "condition": "is",
            "value": current_funct_type,
            "logical_operator": "and"
          });
        }
      }
      /** Module not needed for CSF **/
      if (options.module && current_funct_type != "global" && get_module != "csf" && get_module != "cbf") {
        search_array.push({
          "field": "module.name",
          "condition": "is",
          "value": cf_module,
          "logical_operator": "and"
        });
      }
      if (options.wf_type && current_filter != "all_action") {
        search_array.push({
          "field": "workflow_type",
          "condition": "is",
          "value": current_filter,
          "logical_operator": "and"
        });
      }
      if (options.search) {
        search_array.push({
          "field": "name",
          "condition": "contains",
          "value": options.search,
          "logical_operator": "and"
        });
      }
      // Return search array.
      return search_array;
    },
    // Row data construct
    rowdataConstruct: function rowdataConstruct(table_info, controller) {
      var inputObject = {};
      inputObject.list_info = table_info.list_info;
      inputObject.fields_required = Object.keys(table_info.fields_required);
      controller.module == "cbf" ? inputObject.fields_required.push("is_callback_exposed", "api_name", "callback_url") : "";
      inputObject.list_info.sort_field = "id";
      inputObject.list_info.sort_order = "desc";
      inputObject.list_info.search_criteria = this.getsearchCriteria({
        "function_type": true,
        "module": true,
        "wf_type": true
      });
      return inputObject;
    },
