    updateRoleAssociations: function updateRoleAssociations(_self, userId, roleId) {
      if (_self.associated == true) {
        var selectedRec = _self.table_comp_associated.bulkSelect.getSelectedIDs();
        if (selectedRec.length > 0) {
          sdpAjax({
            url: "api/v3/" + _self.table_comp_associated.t_obj.options.callbackURL + "?ids=" + selectedRec,
            type: "DELETE",
            async: false,
            success: function success(response) {
              _self.showUpdateStatusMessage(response);
              _self.table_comp_associated.refreshTable();
            },
            failure: function failure(response) {
              _self.showUpdateStatusMessage(response.responseJSON);
              _self.table_comp_associated.refreshTable();
            }
          });
        } else {
          alert(translate("common.delete.atleastone"));
        }
      } else {
        var selectedRec = _self.table_comp_unassociated.bulkSelect.getSelectedIDs();
        if (selectedRec.length > 0) {
          var data = [];
          for (var i = 0; i < selectedRec.length; i++) {
            data.push({
              "support_group": {
                "id": selectedRec[i]
              },
              "user": {
                "id": userId
              },
              "group_role": {
                "id": roleId
              }
            });
          }
          sdpAjax({
            url: "api/v3/support_group_role_associations",
            //NO I18N
            type: "POST",
            //NO I18N
            async: false,
            data: sdpAjaxInputData({
              "support_group_role_associations": data
            }),
            success: function success(response) {
              _self.showUpdateStatusMessage(response);
              _self.table_comp_unassociated.refreshTable();
            },
            failure: function failure(response) {
              _self.showUpdateStatusMessage(response.responseJSON);
              _self.table_comp_unassociated.refreshTable();
            }
          });
        } else {
          alert(translate("common.delete.atleastone"));
        }
      }
      _self.parentCtrl.refreshTable();
    },
    showUpdateStatusMessage: function showUpdateStatusMessage(response) {
      var successCount = 0;
      var failureCount = 0;
      response = response.response_status;
      for (var i = 0; i < response.length; i++) {
        if (response[i].status !== "success") {
          failureCount++;
        } else {
          successCount++;
        }
      }
      if (successCount > 0 && failureCount == 0) {
        showalert('success', translate('api.updated.success', [translate('common.associations')]), "isAutoHide=true"); // No I18N
      }
      if (failureCount > 0) {
        showalert('failure', translate('grouprole.update.associations.error', [failureCount]), "isAutoHide=false"); // No I18N
      }
      return;
    }
