                for (var k = 0; k <= 5; k++) {
                  if (obj.eq(k).hasClass('spinner')) {
                    obj.eq(k).parent().removeClass('text-muted').addClass('sb');
                    obj.eq(k).removeClass('spinner').addClass('cspr danger icon-sm');
                    break;
                  }
                }
                jQuery('.DialogBox .sslimportsteps ul.proceeslist li.failure span').removeClass().addClass('cspr danger icon-sm');
                jQuery(".DialogBox").animate({
                  width: "730px"
                }, 500); //NO I18N
                jQuery(".DialogBox #sslprocessfile").show('slow'); //NO I18N
                jQuery(".DialogBox #sslSupportInfo").show('slow'); //NO I18N

                jQuery('#sslprocessfile .msg').html(data.errorInfo);
                for (var j = 0; j <= 5; j++) {
                  if (obj.eq(j).hasClass('spinner')) {
                    obj.eq(j).removeClass('spinner').addClass('cspr success2 icon-sm opac5');
                  }
                }
                jQuery.ajax({
                  url: '/importssl/controller',
                  //NO I18N
                  type: "GET",
                  //NO I18N
                  cache: false,
                  data: {
                    "action": "resetCache"
                  } //NO I18N
                });
                return;
