      sslmodifycer: function sslmodifycer() {
        var modelObj = this.get('model.ssl');
        var modelObjString = JSON.stringify(modelObj);
        var modelJSON = JSON.parse(modelObjString);
        modelJSON.isSelfSigned = true;
        modelJSON.isTrusted = true;
        this.set('isShowCancel', true); //NO I18N
        this.set('model.ssl', modelJSON); //NO I18N
      },
      loadSummaryJson: function loadSummaryJson() {
        var modelObj = this.get('model.ssl');
        var modelObjString = JSON.stringify(modelObj);
        var modelJSON = JSON.parse(modelObjString);
        modelJSON.isSelfSigned = false;
        this.set('model.ssl', modelJSON); //NO I18N
      },
