        var warning_msg = "";
        var success_msg = msg;
        var res = resp.response_status;
        for (var i = 0, len = res.length; i < len; i++) {
          if (res[i].status_code == "2000") {
            successArr.push(res[i].id);
          } else if (res[i].status_code == "3000") {
            warningArr.push(res[i + 1].id);
            warning_msg += e_html(res[i].messages[0].message + (res[i + 1].id ? " [" + res[i + 1].id + "]" : "")) + "</br> ";
          }
        }
        if (warningArr.length) {
          successArr = jQuery(successArr).not(warningArr).get();
          if (successArr.length) {
            success_msg = e_html(success_msg + " [" + successArr + "]") + "</br>";
            success_msg += warning_msg;
            showalert('info', success_msg, "isAutoHide=false"); // No I18N
          } else {
            showalert("info", warning_msg, "isAutoHide=true"); //No I18N
          }
        } else {
          showalert('success', success_msg, "isAutoHide=true"); // No I18N
        }
