      initChannelSelect: function initChannelSelect() {
        var teamsChannels = this.get('teamsChannels');
        var teamsSelectData = [];
        for (var teamID in teamsChannels) {
          var teamGroup = {};
          if (teamsChannels.hasOwnProperty(teamID)) {
            var teamData = teamsChannels[teamID];
            teamGroup.text = teamData.name;
            var children = [];
            if (teamData.conversations) {
              teamData.conversations.forEach(function (conversation) {
                var idObject = {
                  teamID: teamData.id,
                  channelID: conversation.id
                };
                idObject = sdpToJSON(idObject);
                var child = {
                  "id": idObject,
                  "text": conversation.name ? conversation.name : translate("sdp.admin.settings.general")
                };
                children.push(child);
              });
            }
            teamGroup.children = children;
          }
          teamsSelectData.push(teamGroup);
        }
        this.set("teamSelectData", teamsSelectData);
        this.send("renderChannelSelect");
      },
