    replaceTemplateValues: function replaceTemplateValues(params, config) {
      for (var param in params) {
        if (params.hasOwnProperty(param)) {
          var tempValue = params[param];
          if (tempValue.includes('${')) {
            tempValue = tempValue.substring(2, tempValue.length - 1);
            if (config[tempValue] != null) {
              params[param] = config[tempValue];
            }
          }
        }
      }
      return params;
    },
