      ct_APICall: function ct_APICall(ele) {
        var isServTemp = this.get("isServiceTemplate");
        var selCategory = this.get('selServiceCat');
        var no_of_copies = this.get('no_of_copies');
        var copy_as_inactive = this.get("copy_as_inactive");
        var tempId = this.get('model').id;
        no_of_copies = parseInt(no_of_copies);
        if (no_of_copies <= 5) {
          var copy_json = {};
          copy_json.no_of_copies = no_of_copies;
          copy_json.copy_as_inactive = copy_as_inactive;
          if (isServTemp) {
            var selCategory = this.get('selServiceCat');
            delete selCategory['description'];
            copy_json.service_category = selCategory;
          } else {
            var copyto = this.get("copyto");
            copy_json.copyto = copyto;
            if (copyto === "service") {
              var selCategory = this.get('selServiceCat');
              copy_json.service_category = selCategory;
            }
          }
          var inputData = {
            "request_templates": copy_json
          }; //NO I18N

          var strJson = JSON.stringify(inputData);
          sdpAjax({
            type: 'POST',
            //NO I18N
            url: '/api/v3/request_templates/' + tempId + '/copyTemplate',
            // No I18N
            data: {
              'input_data': strJson
            },
            //NO I18N
            success: function success(res) {
              var tempRules = res.request_template.template_rules;
              var successMsg = "",
                failureMsg = "";
              //To structure the success and failure message
              for (var j = 0; j < tempRules.message.length; j++) {
                if (tempRules.message.type == "success") {
                  successMsg += "<strong>" + e_html(tempRules.templateName) + ":</strong><br/>" + tempRules.message[j].message; //no i18n
                } else if (tempRules.message[j].type == "failure") {
                  failureMsg += "<strong>" + e_html(tempRules.templateName) + ":</strong><br/>" + tempRules.message[j].message; //no i18n
                }
              }
              var msg = res.response_status.messages[0].message;
              showalert('success', msg, 'isAutoHide=true'); //NO I18N
              if (tempRules != null) {
                if (successMsg !== "") {
                  showalert('success', successMsg, 'isAutoHide=true,delay=3'); //NO I18N
                }
                if (failureMsg !== "") {
                  showalert("failure", failureMsg, 'isAutoHide=false,delay=30'); // No I18N}
                }
              }
              ele.parents('#copyTemplateSection').dialog('close'); //NO I18N
            }
          });
        } else {
          var msg = window.translate('sdp.admin.servicecatalog.copyTemplate.valErrMsg');
          showalert('failure', msg, 'isAutoHide=true,delay=20'); //NO I18N
        }
      },
