      templateAPICall: function templateAPICall(input_json, method_type, current_tab, navToNewPage) {
        var _self = this;
        var stringified_json = JSON.stringify(input_json);
        var inputData = {
          "input_data": stringified_json
        }; //No I18N
        var model = this.get("model");
        var mode = this.get("mode"); //No I18N
        var tempId = mode == "edit" ? model.id : ''; //No I18N
        var apiResultStatus = "failure"; //NO I18N
        var isServTemp = this.get("isServiceTemplate");
        var routeName = isServTemp ? 'admin.service-templates.edit' : 'admin.request-templates.edit'; //NO I18N
        var scrollPos = $(window).scrollTop();
        //for csrf token
        inputData[getCSRFParamName()] = getCSRFParamValue();
        sdpAjax({
          type: method_type,
          url: '/api/v3/request_templates/' + tempId,
          // No I18N
          data: inputData,
          success: function success(res) {
            var resultJson = res.response_status.messages[0];
            var message = resultJson.message;
            if (res.response_status.status == "success") {
              apiResultStatus = "success"; //NO I18N
              _self.send('headerRefresh'); //NO I18N
              //$("#reqTempHTMLDesc_INLINEIMAGES option").remove();

              //edit template
              if (mode == "edit") {
                //No I18N

                //save template called navToNewPage(workflow/fafr) ,this action should not be done
                if (!navToNewPage) {
                  var timeSecs = 5;
                  $('.sdtab-content').addClass('hide');
                  _self.set("leftNavCall", false); //NO I18N
                  _self.send('refreshModel'); //NO I18N

                  //navigate to requester tab from technician tab after Saving
                  if (current_tab == "requesterTab") {
                    timeSecs = 50;
                    _self.set('moveReqTab', true); //NO I18N
                  }
                  setTimeout(function () {
                    $('.sdtab-content').removeClass('hide');
                    $("[name='fieldsearch']").trigger('keyup');
                    $(window).scrollTop(scrollPos);
                    $('.formtmpl-fields .sdtab-pane #searchNtFnd').remove();
                    $("[name='fieldsearch']").val('');
                  }, timeSecs);
                } else {
                  _self.set("leftNavCall", false); //NO I18N
                }
              }
              //new template
              else {
                tempId = res.request_template.id;
                _self.set("mode", "edit"); //No I18N

                $(window).scrollTop(0);
                if (current_tab == 'requesterTab') {
                  _self.set("moveReqTab", true); //NO I18N
                }
                _self.transitionToRoute(routeName, tempId);
              }
              _self.setProperties({
                'sgForRender': true,
                'ugForRender': true
              }); //No I18N
              $("#imgIcon").addClass('hide');
              //settimeout is given because it will take some to render the template
              setTimeout(function () {
                $("#templatecomments").trigger('keyup');
                var delay = apiResultStatus == 'success' ? 2 : 10; //NO I18N
                showalert(apiResultStatus, message, 'delay=' + delay); //NO I18N
              }, 40);
              if (navToNewPage) {
                var movingTab = _self.get("movingTab");
                _self.send('moveToOtherTab', movingTab); //NO I18N
              }
            } else {
              _self.set('opSuccess', false); //No I18N
              if (resultJson.fields) {
                _self.modifyUDFIdForInvalidField(message, resultJson.fields[0]);
              } else {
                _self.modifyUDFId(message);
              }
              $("#imgIcon").addClass('hide');
            }
          },
          error: function error(resp) {
            var msg = resp.responseJSON.response_status.messages[0];
            var message = msg.message;
            if (msg.field) {
              message = "".concat(msg.field, " - ").concat(message);
            }
            _self.set('opSuccess', false); //No I18N
            showalert("failure", message, 'isAutoHide=false'); //NO I18N
            $("#imgIcon").addClass('hide');
          },
          async: false,
          cache: false
        });
      },
