          var msg = cntrlr.moduleName == 'release' && this.get("rolesDefaultvalcng") ? window.translate('sdp.admin.layout.change.msg.alert') : window.translate('layout.prop.change.msg.alert');
          var alertTitle = window.translate('common.confirm.submit.msg');
          var saveBtn = window.translate("sdp.common.save");
          var discardBtn = window.translate("common.discard");
          showconfirm(true, 'title=' + alertTitle + ', message=' + msg + ', submitbutton=' + saveBtn + ', cancelbutton=' + discardBtn + ', closebutton=yes, closeOnEscKey=yes', showconfirmcommit);
