    // Method to unify different formats of refer entity questions and manual questions wrt UI
    formatOptionsArray: function formatOptionsArray(options, hasCost) {
      if (options != undefined) {
        var modifiedOptions = [];
        for (var i = 0; i < options.length; i++) {
          var optionObj = options[i];
          optionObj.order = i.toString();
          if (optionObj.pictures != undefined) {
            var images = [];
            var primay_image_index = -1;
            for (var j = 0; j < optionObj.pictures.length; j++) {
              if (optionObj.pictures[j].primary && j != 0) {
                images.splice(0, 0, optionObj.pictures[j]['content-url']);
                primay_image_index = j;
              } else {
                images.push(optionObj.pictures[j]['content-url']);
              }
            }
            //Need to replace the pictures in optionObj, since selected image in img-slider will based on index of optionObj.images.
            if (primay_image_index != -1 && primay_image_index != 0) {
              var primary_picture = optionObj.pictures[primay_image_index];
              /**
               * In Ember 3.28, the removeAt method has stricter validation, and passing undefined as an index is no longer allowed.
               */
              if (primay_image_index !== undefined) {
                optionObj.pictures.removeAt(primay_image_index, 1);
              }
              optionObj.pictures.insertAt(0, primary_picture);
            }
            optionObj.images = images;
          }
          if (optionObj.additional_attributes != undefined) {
            var additional_attributes = optionObj.additional_attributes;
            if (hasCost) {
              if (additional_attributes.cost) {
                optionObj.cost = additional_attributes.cost;
              }
              if (!optionObj.cost) {
                optionObj.cost = '0.00';
              }
            }
            if (additional_attributes.description) {
              optionObj.description = additional_attributes.description;
            }
            delete optionObj.additional_attributes;
          }
          if (!hasCost) {
            delete optionObj.cost;
          }
          modifiedOptions.push(optionObj);
        }
        return modifiedOptions;
      }
      return options;
    },
