    getReferCriteria: function getReferCriteria(criteria) {
      if (criteria != undefined) {
        criteria.forEach(function (criterion) {
          if (criterion.values) {
            criterion.values = criterion.values.map(function (value) {
              if (typeof value === "string") {
                try {
                  return JSON.parse(value);
                } catch (e) {
                  return value;
                }
              }
              return value;
            });
            delete criterion.display_value;
          }
        });
      }
      return criteria;
    },
    quesAjax: function quesAjax(question, parentModule) {
      //resource section associated question allowed value and option updated
      var arr = [];
      if (parentModule != undefined) {
        parentModule.set('qnsopt', null); //NO I18N
      }
      var url = '/api/v3/udf_fields/' + question.id + '/options';
      var listInfo = {
        "start_index": 1,
        "row_count": 100
      };
      var inputData = {};
      var isManual = true;
      var refer_search_criteria;
      inputData.list_info = listInfo;
      if (question.reference_entity != null) {
        isManual = false;
        url = '/api/v3/udf_fields/reference_entity_preview';
        inputData.module = {
          "name": "request"
        };
        inputData.reference_entity = question.reference_entity;
        inputData.name = question.name;
        inputData.additional_attributes = {};
        inputData.additional_attributes.sort_order = 'asc';
        if (question.additional_attributes && question.additional_attributes.sort_order) {
          inputData.additional_attributes.sort_order = question.additional_attributes.sort_order;
        }
        if (question.criteria) {
          refer_search_criteria = this.getReferCriteria(question.criteria);
        }
      } else {
        //For manual options, only active options has to be fetched.
        inputData.list_info.search_criteria = [{
          "field": "deleted",
          "condition": "is",
          "value": false,
          "logical_operator": "and"
        }];
      }
      var successFunc = function successFunc(res) {
        var options = isManual ? res['options'] : res[question.name];
        hasMoreRows = res.list_info.has_more_rows;
        if (hasMoreRows) {
          listInfo.start_index = listInfo.start_index + 100;
        }
        if (question.reference_entity != null) {
          //For product and software primary image alone will come in allowed values call. For complete images, need to do get while editing option
          var keyToFtech = 'product' == question.reference_entity.name ? 'product_primary_icon' : 'software_primary_image';
          for (var i = 0; i < options.length; i++) {
            var pictures = [];
            if (options[i][keyToFtech] != null) {
              pictures.push(options[i][keyToFtech]);
            }
            options[i].pictures = pictures;
          }
        }
        arr = arr.concat(options);
        if (parentModule != undefined) {
          parentModule.set('qnsopt', arr); //NO I18N
        }
      };
      var errorFunc = function errorFunc(data) {
        arr = null;
        hasMoreRows = false;
        if (parentModule != undefined) {
          parentModule.set('qnsopt', null); //NO I18N
        }
      };

      /* Iterating each criteria because, when the count of options is greater than 500, combined call will fail due to large size of the input_data */
      if (refer_search_criteria) {
        var criteria_length = refer_search_criteria.length;
        for (var i = 0; i < criteria_length; i++) {
          if (!jQuery.isEmptyObject(refer_search_criteria[i])) {
            inputData.list_info.search_criteria = [refer_search_criteria[i]];
            sdpAjax({
              url: url,
              async: false,
              data: {
                "input_data": sdpToJSON(inputData)
              },
              success: successFunc,
              error: errorFunc
            });
          }
        }
      } else {
        var hasMoreRows = true;
        while (hasMoreRows) {
          sdpAjax({
            url: url,
            async: false,
            data: {
              "input_data": sdpToJSON(inputData)
            },
            success: successFunc,
            error: errorFunc
          });
          /* Need to get first 100 options alone, when a resource question has no criteria (Refer question flow comes here, only when no criteria is present) */
          if (question.reference_entity) {
            break;
          }
        }
      }
      return arr;
    },
