    criVallengthfn: function criVallengthfn(rule_criteria) {
      //for criteria option value not more than 100
      for (var i = 0; i < rule_criteria.length; i++) {
        if (rule_criteria[i].children != undefined) {
          this.criVallengthfn(rule_criteria[i].children);
        }
        if (rule_criteria[i].field == 'site') {
          var val = rule_criteria[i].values;
          if (val) {
            for (var j = 0; j < val.length; j++) {
              if (val[j].id && val[j].id == '-1') {
                val[j] = null;
              }
            }
          }
        }
        if (rule_criteria[i].values != null && rule_criteria[i].values.length > 100) {
          this.criVallength = false;
        }
      }
      return this.criVallength;
    },
