    transformSubCatAndItemValfn: function transformSubCatAndItemValfn(crit) {
      if (crit) {
        for (var i = 0; i < crit.length; i++) {
          var critval = crit[i].values;
          if (critval) {
            for (var j = 0; j < critval.length; j++) {
              //SD-120202 When critval[j].category is null, console error thrown and criteria section is not rendered
              if (critval[j] == null) {
                continue;
              }
              if (crit[i].field == "subcategory" && critval[j].category && critval[j].name.includes(critval[j].category.name + " > ")) {
                var category = critval[j].category.name;
                critval[j].name = critval[j].name.slice(critval[j].name.search(category) + category.length + 3);
              }
              if (crit[i].field == "item" && critval[j].subcategory && critval[j].name.includes(critval[j].subcategory.name + " > ")) {
                var subcategory = critval[j].subcategory.name;
                critval[j].name = critval[j].name.slice(critval[j].name.search(subcategory) + subcategory.length + 3);
              }
            }
          }
          if (crit[i].children != undefined) {
            this.transformSubCatAndItemValfn(crit[i].children);
          }
        }
      }
    }
