    /*Indent code before copying to CodeMirror editor*/
    simpleIndentCode: function simpleIndentCode(codeString) {
      var indentedCode = '';
      for (var i = 0, len = codeString.length; i < len; i++) {
        var codeChar = codeString[i];
        if (codeChar === '{') {
          indentedCode += codeChar + '\n'; //NO I18N
        } else if (codeChar === '}' && i !== len - 1) {
          indentedCode += codeChar + '\n'; //NO I18N
        } else if (codeChar === ';' && i !== len - 1) {
          indentedCode += codeChar + '\n'; //NO I18N
        } else if (codeChar === '/' && codeString[i - 1] === '*') {
          indentedCode += codeChar + '\n'; //NO I18N
        } else {
          indentedCode += codeChar;
        }
      }
      return indentedCode;
    },
