            if (_typeof(v) === "object") {
              obj = {
                TITLE: v.value || v.name,
                VALUE: fieldID.indexOf("RES_") == -1 ? v.id : i
              };
              if (v.cost) {
                obj.TITLE = obj.TITLE + " - " + sdp_app.CURRENCY_SYMBOL + v.cost;
              }
            } else {
              obj = {
                TITLE: v,
                VALUE: i
              };
            }
