      setModule: function setModule(module) {
        cntrlr.glbRuleEvent = module;
        jQuery("#fafr_list_div").html("");
        this.renderFafrRulesAndListViewTable().initilizeForm(cntrlr);
        cntrlr.$fAFR().showView("ffr-listview"); //NO I18N
        cntrlr.$fAFRList().setFafrListView();
      },
