      /* Delete rules button from rules popup list view.
      */
      deleteRulesFromListView: function deleteRulesFromListView() {
        // Get Bulk selected id.
        var controller = this;
        var selected_rule_type = controller.selected_rule_type;
        var config = controller.timer_config;
        var table_component = this.get('table_comp_' + selected_rule_type);
        var bulk_sel_ids = table_component.bulkSelect.getSelectedIDs();
        if (bulk_sel_ids.length == 0) {
          showalert('warning', translate("common.delete.atleastone"), "isAutoHide=true,delay=4,closeOnEscKey=yes"); // No I18N
          return false;
        }
        function deleteRules(selectedOption) {
          if (selectedOption) {
            var input_data = null;
            var url = selected_rule_type == "during_rules" ? "/api/v3/" + config.during_rules_config.during_rule_url : "/api/v3/" + config.after_rules_config.after_rule_url;
            var rule_ids = '';
            jQuery.each(bulk_sel_ids, function (index, selectedIds) {
              rule_ids = rule_ids != '' ? rule_ids + ',' + selectedIds : selectedIds;
            });
            // Bulk edit stored in input data object.
            input_data = {
              "ids": rule_ids
            };
            sdpAjax({
              url: url,
              type: "DELETE",
              data: input_data,
              async: false,
              success: function success() {
                // Get delete message key.
                showalert('success', translate('sdp.admin.orgrole.messages.success.delete'), "isAutoHide=true,delay=4,closeOnEscKey=yes"); // No I18N
                //Deleting rules in current timer's stages if already associated.
                var stages = controller.model.timer_data.stages;
                for (i = 0; i < stages.length; i++) {
                  var rules = stages[i][selected_rule_type];
                  jQuery.each(bulk_sel_ids, function (i, id) {
                    //NO I18N
                    var index = $wfRuleUtil.timerAction.findIndexForRules(rules, parseInt(id));
                    rules.removeObject(rules[index]);
                  });
                }
              },
              error: function error(jqXHR) {
                showalert('failure', translate("sdp.vulnerability.error.unknownexception.msg"), "isAutoHide=true,delay=4,closeOnEscKey=yes"); // No I18N
              }
            });
            // Refresh table component.
            table_component.refreshTable();
          }
        }
        var deletemsg = translate('timer.rules.list.confirm', ['<b>' + translate('sdp.itil.propview.deleted') + '</b>']);
        showconfirm(true, 'title=' + translate("sdp.backupapprover.conformdelete") + ', message=' + deletemsg + ', submitbutton=' + translate("sdp.admin.translation.proceed") + ', cancelbutton=' + translate("sdp.common.cancel") + ', closebutton=yes, closeOnEscKey=yes', deleteRules);
      },
