      /* Display list of associated workflow entries in "Active in" popup.
      * @param params as provided in clickaction. <timer_action,rule_id>
      * @param ele - clickaction anchor element, Cannot remove this argument as this is passed by clickaction. Need controller object as next argument.
      * @param controller
      */
      viewAssociatedEntries: function viewAssociatedEntries(params, ele, controller) {
        var wf_type,
          ruleid,
          input_data = {},
          list_info = {
            "row_count": "100"
          },
          options;
        options = params.split(',');
        // Set work flow type.
        wf_type = options[0];
        // Set rule id.
        ruleid = options[1];
        var cntrl = controller ? controller : this;
        var config, rule_url, rule_type;
        if (cntrl.selected_rule_type == 'during_rules') {
          config = cntrl.timer_config.during_rules_config;
          rule_url = cntrl.timer_config.during_rules_config.during_rule_url;
          rule_type = cntrl.timer_config.during_rules_config.during_rule_type;
        } else {
          config = cntrl.timer_config.after_rules_config;
          rule_url = cntrl.timer_config.after_rules_config.after_rule_url;
          rule_type = cntrl.timer_config.after_rules_config.after_rule_type;
        }
        var search_array = [];
        search_array.push({
          "field": "rule_type",
          "condition": "is",
          "value": rule_type,
          "logical_operator": "and"
        });
        search_array.push({
          "field": "module",
          "condition": "is",
          "value": cntrl.timer_config.module_name,
          "logical_operator": "and"
        });
        list_info.search_criteria = search_array;
        input_data.list_info = list_info;
        var url = '/api/v3/' + rule_url + '/' + ruleid + "/get_associated_workflows"; //No I18N
        // Get work flow data
        cntrl.getAssociatedWorkflow({
          "url": url,
          "input": input_data,
          "cntrl": cntrl
        }, function (data) {
          //success callback.
          jQuery("#workflow_list").html("");
          var associated_workflows = data.associated_workflows;
          // If work flow length equal to 0.call below if check.
          if (associated_workflows.length == 0) {
            jQuery("#workflow_list").html("<div class='p15' align='center'>" + translate("sdp.app.common.noresults") + "</div>");
            // If work flow length not equal to 0.call below else check.
          } else {
            // Iterate workflow object.
            jQuery.each(associated_workflows, function (index, stage) {
              var timerJSON = stage.timer;
              if (timerJSON && timerJSON.description != null) {
                var des = timerJSON.description;
                if (des.length > 500) {
                  des = des.substring(0, 500);
                }
                var desc = '<p class="text-muted">' + e_html(des) + '</p>';
              } else {
                var desc = '';
              }
              var timerName = stage.timer.name + ' >> ' + translate('request.approve.stage') + stage.stage_number;
              if (stage.name) {
                timerName += ' (' + stage.name + ')';
              }
              var url = '/app#/admin/timeractions/' + cntrl.model.routeName + '/' + timerJSON.id;
              var divStr = '<div class="tc-row pb5" data-id="rcf-list-view"><p class="sb title text-color4">' + e_html(timerName);
              divStr += '<a href="' + url + '" data-id="active_in_timer_stage_' + timerJSON.id + '" target="_blank" class="flat ml10"><span class="cspr flat icon-sm newtab"></span></a>';
              divStr += desc;
              jQuery("#workflow_list").append(divStr);
            });
          }
          // Show work flow dialog.
          jQuery('#work_flow').dialog({
            resizable: false,
            width: 950,
            maxHeight: jQuery(window).height(),
            draggable: false,
            position: {
              my: "center top",
              at: "center top+0",
              of: window
            },
            //NO I18N
            modal: true,
            close: function close() {
              // Remove dialog.
              $("#work_flow").dialog('destroy');
            }
          });
          // Set filter value.
          jQuery("#active-popup-filter").text(translate("timer.stages"));
        }, function (jqXHR) {
          //failue callback
          //Error message checks.
          var response = JSON.parse(jqXHR.responseText),
            messages = response.response_status.messages[0],
            err_msg = "";
          if (messages != undefined && messages.message != undefined) {
            err_msg = e_html(messages.message);
          } else {
            err_msg = translate("sdp.common.failed");
          }
          showalert('failure', err_msg, "isAutoHide=true,delay=4,closeOnEscKey=yes"); // No I18N
        });
      },
