    // Get associate timer count data.
    getAssociatedWorkflow: function getAssociatedWorkflow(options, successCallBack, failureCallBack) {
      var self = this;
      !options.cntrl.timer_st_count || options.cntrl.timer_st_count == "" ? options.cntrl.timer_st_count = 1 : "";
      options.input.list_info.start_index = options.cntrl.timer_st_count;
      sdpAjax({
        url: options.url,
        type: "GET",
        data: sdpAjaxInputData(options.input),
        async: false,
        cache: false,
        success: function success(data) {
          // If (has more rows) true. call below if check.
          if (data.list_info.has_more_rows) {
            self.data_obj = self.data_obj.concat(data.associated_workflows);
            self.timer_st_count = self.timer_st_count + 100;
            self.getAssociatedWorkflow(options, successCallBack, failureCallBack);
          }
          // If (has more rows) false. call below else check.
          else {
            data.list_info.start_index == 1 ? self.data_obj = data.associated_workflows : self.data_obj = self.data_obj.concat(data.associated_workflows);
            if (typeof successCallBack === "function") {
              //No I18N
              // Set associate work flow data.
              successCallBack({
                associated_workflows: self.data_obj
              });
            }
          }
        },
        error: function error(jqXHR) {
          if (typeof failureCallBack === "function") {
            //No I18N
            // Error message call back.
            failureCallBack(jqXHR);
          }
        }
      });
      options.cntrl.timer_st_count = "";
      options.cntrl.data_obj = [];
    },
