    /*listview enable. disable for single and bulk operation
    * @param selectedOption - enable/disable
    * @param tableDataObject -  table component objects
    * @param id - rule id
    */
    listviewCommonAction: function listviewCommonAction(selectedOption, tableDataObj, id) {
      var updateJson, confirmMsg;
      var _self = this;
      var config = _self.timer_config;
      var rule_url = "";
      if (_self.selected_rule_type == 'during_rules') {
        config = _self.timer_config.during_rules_config;
        rule_url = _self.timer_config.during_rules_config.during_rule_url;
      } else {
        config = _self.timer_config.after_rules_config;
        rule_url = _self.timer_config.after_rules_config.after_rule_url;
      }
      switch (selectedOption) {
        case "enable":
          updateJson = {
            "is_enabled": true
          };
          confirmMsg = translate('timer.rules.list.confirm', ['<b>' + translate('sdp.requests.fieldFormRules.rules.enabled') + '</b>']);
          break;
        case "disable":
          updateJson = {
            "is_enabled": false
          };
          confirmMsg = translate('timer.rules.list.confirm', ['<b>' + translate('sdp.requests.fieldFormRules.rules.disabled') + '</b>']);
          break;
      }
      var msg = translate('api.updated.success', [translate('common.rules')]);
      var reqform = config.entity_key_singular;
      var json_data = {};
      json_data[reqform] = updateJson;
      if (id != null && id != undefined) {
        //in single rule change event
        var url = '/api/v3/' + rule_url + '/' + id;
        if ($wfRuleUtil.timerAction.listviewCommonAjax(url, json_data, msg)) {
          var rules_table_component = this.get('table_comp_' + this.selected_rule_type);
          rules_table_component.refreshTable('search');
          var selectedRulesFromListView = rules_table_component.bulkSelect.selectedRecords; //updating in selected records if the rule is already selected.
          if (selectedRulesFromListView && selectedRulesFromListView[id]) {
            selectedRulesFromListView[id].is_enabled = updateJson.is_enabled;
          }
          $wfRuleUtil.timerAction.updateRuleDetailToStageRules(this, id, selectedOption == "enable");
        }
      } else {
        //in bulk rules changes events
        var selectedRules = [];
        $.each(tableDataObj.bulkSelect.selectedRecords, function (index, value) {
          selectedRules.push(index);
        });
        if (selectedRules.length != 0) {
          var bractsubmit = function bractsubmit(s) {
            if (s) {
              if ($wfRuleUtil.timerAction.listviewCommonAjax(url, json_data, msg, tableDataObj)) {
                for (var i = 0; i < selectedRules.length; i++) {
                  $wfRuleUtil.timerAction.updateRuleDetailToStageRules(_selfthis, selectedRules[i], selectedOption == "enable");
                }
              }
            }
          };
          var url = '/api/v3/' + rule_url + '?ids=' + selectedRules.toString();
          var _selfthis = this;
          showconfirm(true, 'title=' + translate("common.confirm.submit.msg") + ', message=' + confirmMsg + ', submitbutton=' + translate("sdp.admin.translation.proceed") + ', cancelbutton=' + translate("sdp.common.cancel") + ', closebutton=yes, closeOnEscKey=yes', bractsubmit);
        }
      }
    },
