    /* returns default rule filter criteria
    */
    getRulesFilterCriteria: function getRulesFilterCriteria() {
      var controller = this;
      var search_criteria = [];
      if (controller.rule_list_filter == "unassociated_rules") {
        if (controller.model.temp_selected_rules) {
          var selectedRuleIDs = [];
          controller.model.temp_selected_rules.forEach(function (val) {
            selectedRuleIDs.push(val.rule.id);
          }); //temp_selected_rules will be initialized when addDuringRules/addAfterRules method is invoked.
          if (selectedRuleIDs.length > 0) {
            search_criteria = [{
              'field': 'id',
              'condition': 'is not',
              'values': selectedRuleIDs,
              'logical_operator': 'and'
            }]; // id "is not" <already assoicated rules
          }
          if (controller.timer_config.has_extended_module_filter) {
            search_criteria.push({
              'field': 'extended_module.id',
              'value': controller.extended_modules_data.selected_extended_module.id,
              'condition': 'is',
              'logical_operator': 'and'
            });
          }
        }
      }
      return search_criteria;
    },
